const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Cabo Frio is known for coastal upwelling, making it a plausible location for strong SST gradients.
  const caboFrio = ee.Geometry.Point([-42.0274, -22.8797]);
  // Create an area of interest (AOI) extending into the sea.
  // A 30km buffer should be sufficient to analyze gradients over a 10km distance.
  const aoi = caboFrio.buffer(30000);
  const startDate = '2023-09-01';
  const endDate = '2023-09-30';

  // 2. Data Acquisition & Check
  // JPL MUR SST is a daily, 1km resolution dataset, suitable for this analysis.
  // The 'analysed_sst' band is in Kelvin, so it needs conversion to Celsius.
  const sstCollection = ee.ImageCollection("JPL/MUR/L4/GLOB/v4.1")
    .filterDate(startDate, endDate)
    .filterBounds(aoi)
    .select('analysed_sst');

  const collectionSize = sstCollection.size().getInfo();
  if (collectionSize === 0) {
    console.log("No images found for the specified date and location.");
    console.log("A");
    return;
  }

  // 3. Processing
  // Create a single mean composite image for the month.
  const sstMeanKelvin = sstCollection.mean();
  // Convert from Kelvin to Celsius.
  const sstMeanCelsius = sstMeanKelvin.subtract(273.15);

  // Check for valid pixels in the composite image before proceeding.
  const pixelCount = sstMeanCelsius.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: aoi,
    scale: 1000,
    maxPixels: 1e9
  }).get('analysed_sst').getInfo();

  if (!pixelCount || pixelCount === 0) {
    console.log("No valid pixels found in the SST composite for the region.");
    console.log("C2");
    return;
  }

  // Calculate the temperature gradient. The result is the magnitude of the gradient vector.
  // The units will be in degrees Celsius per meter.
  const gradient = sstMeanCelsius.gradient().magnitude();

  // 4. Calculation
  // Find the maximum gradient value within the AOI.
  const maxGradient = gradient.reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: aoi,
    scale: 1000, // Use a scale appropriate for the 1km dataset to avoid timeout.
    maxPixels: 1e9,
    bestEffort: true
  });

  const maxGradientValue = maxGradient.get('magnitude').getInfo();

  if (maxGradientValue === null || typeof maxGradientValue === 'undefined') {
    console.log("Failed to calculate the maximum gradient.");
    console.log("C3");
    return;
  }

  // Convert the gradient from degrees/meter to degrees/10km for comparison.
  const maxGradientPer10km = maxGradientValue * 10000;
  const threshold = 5.0; // 5 degrees Celsius

  // 5. Validation & Final Answer
  console.log(`Date Range: ${startDate} to ${endDate}`);
  console.log(`Source Images Found: ${collectionSize}`);
  console.log(`Valid Pixels in Composite: ${pixelCount}`);
  console.log(`Maximum SST Gradient (degC/meter): ${maxGradientValue.toExponential(4)}`);
  console.log(`Equivalent Max Gradient (degC/10km): ${maxGradientPer10km.toFixed(2)}`);
  console.log(`Threshold for 'Yes' (degC/10km): > ${threshold}`);

  if (maxGradientPer10km > threshold) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error(`Initialization or Analysis failed: ${e}`);
    console.log("D");
  }
}

initEE();
